/**
 * Action runtime shared types.
 *
 * Contains data contracts used by the action registry, action overlay,
 * and ActionPanel extraction helpers.
 */

export interface ActionShortcut {
  modifiers?: string[];
  key?: string;
}

export interface ActionRegistration {
  id: string;
  title: string;
  icon?: any;
  shortcut?: ActionShortcut;
  style?: string;
  sectionTitle?: string;
  execute: () => void;
  order: number;
}

export interface ActionRegistryAPI {
  register: (id: string, data: Omit<ActionRegistration, 'id'>) => void;
  unregister: (id: string) => void;
}

export interface ExtractedAction {
  title: string;
  icon?: any;
  shortcut?: ActionShortcut;
  style?: string;
  sectionTitle?: string;
  execute: () => void;
}

/**
 * Action runtime keyboard helpers.
 *
 * Provides shortcut matching utilities and the keyboard shortcut renderer
 * used by action overlays and footer affordances.
 */

import React from 'react';
import type { ActionShortcut } from './action-runtime-types';

const shortcutBadgeClassName =
  'inline-flex items-center justify-center min-w-[22px] h-[22px] px-1.5 rounded bg-[var(--kbd-bg)] text-[11px] text-[var(--text-subtle)] font-medium';

/**
 * Normalize platform-specific shortcut objects.
 * Raycast supports: { key, modifiers } or { macOS: { key, modifiers }, Windows: { key, modifiers } }
 */
export function normalizeShortcut(shortcut?: any): ActionShortcut | undefined {
  if (!shortcut) return undefined;
  // Already flat format: { key, modifiers }
  if (shortcut.key) return shortcut as ActionShortcut;
  // Platform-specific format: { macOS: { key, modifiers }, Windows: { key, modifiers } }
  const platformKey = process.platform === 'darwin' ? 'macOS' : 'Windows';
  const platformShortcut = shortcut[platformKey] || shortcut.macOS || shortcut.Windows;
  if (platformShortcut?.key) return platformShortcut as ActionShortcut;
  return undefined;
}

export function renderShortcutKeycap(label: string, key?: React.Key): React.ReactNode {
  return (
    <kbd key={key} className={shortcutBadgeClassName}>
      {label}
    </kbd>
  );
}

export function matchesShortcut(e: React.KeyboardEvent | KeyboardEvent, rawShortcut?: ActionShortcut): boolean {
  const shortcut = normalizeShortcut(rawShortcut);
  if (!shortcut?.key) return false;
  const shortcutKey = shortcut.key.toLowerCase();
  const eventKey = e.key.toLowerCase();
  const eventCode = ((e as any).code || '').toLowerCase();

  const keyMatch = eventKey === shortcutKey;
  const codeMatch =
    shortcutKey.length === 1 &&
    /^[a-z]$/.test(shortcutKey) &&
    eventCode === `key${shortcutKey}`;
  if (!keyMatch && !codeMatch) return false;

  const modifiers = shortcut.modifiers || [];
  // Hyper shortcuts are handled by the native monitor, not DOM events
  if (modifiers.includes('hyper')) return false;
  if (modifiers.includes('cmd') !== e.metaKey) return false;
  if ((modifiers.includes('opt') || modifiers.includes('option') || modifiers.includes('alt')) !== e.altKey) return false;
  if (modifiers.includes('shift') !== e.shiftKey) return false;
  if (modifiers.includes('ctrl') !== e.ctrlKey) return false;
  return true;
}

export function isMetaK(e: React.KeyboardEvent | KeyboardEvent): boolean {
  return e.metaKey && String(e.key || '').toLowerCase() === 'k';
}

export function renderShortcut(rawShortcut?: ActionShortcut): React.ReactNode {
  const shortcut = normalizeShortcut(rawShortcut);
  if (!shortcut?.key) return null;

  const parts: string[] = [];
  for (const mod of shortcut.modifiers || []) {
    if (mod === 'cmd') parts.push('⌘');
    else if (mod === 'opt' || mod === 'alt') parts.push('⌥');
    else if (mod === 'shift') parts.push('⇧');
    else if (mod === 'ctrl') parts.push('⌃');
    else if (mod === 'hyper') parts.push('✦');
  }

  return (
    <span className="flex items-center gap-1 ml-auto">
      {parts.map((symbol, index) => (
        renderShortcutKeycap(symbol, index)
      ))}
      {renderShortcutKeycap(shortcut.key.toUpperCase(), 'key')}
    </span>
  );
}

/**
 * Action runtime overlay and extraction layer.
 *
 * Provides static fallback extraction from ActionPanel trees and the
 * command palette style action overlay renderer.
 */

import React, { useEffect, useRef, useState } from 'react';
import type { ExtractedAction } from './action-runtime-types';
import { resolveIconSrc } from './icon-runtime-assets';

interface OverlayDeps {
  snapshotExtensionContext: () => any;
  inferActionTitle: (props: any, kind?: string) => string;
  makeActionExecutor: (props: any, runtimeCtx?: any) => () => void;
  renderIcon: (icon: any, className?: string, assetsPath?: string) => React.ReactNode;
  matchesShortcut: (e: React.KeyboardEvent | KeyboardEvent, shortcut?: { modifiers?: string[]; key?: string }) => boolean;
  isMetaK: (e: React.KeyboardEvent | KeyboardEvent) => boolean;
  renderShortcut: (shortcut?: { modifiers?: string[]; key?: string }) => React.ReactNode;
  renderShortcutKeycap: (label: string, key?: React.Key) => React.ReactNode;
}

export function createActionOverlayRuntime(deps: OverlayDeps) {
  const {
    snapshotExtensionContext,
    inferActionTitle,
    makeActionExecutor,
    renderIcon,
    matchesShortcut,
    isMetaK,
    renderShortcut,
    renderShortcutKeycap,
  } = deps;

  function extractActionsFromElement(element: React.ReactElement | undefined | null): ExtractedAction[] {
    if (!element) return [];

    const result: ExtractedAction[] = [];
    const runtimeCtx = snapshotExtensionContext();

    function walk(nodes: React.ReactNode, sectionTitle?: string) {
      React.Children.forEach(nodes, (child) => {
        if (!React.isValidElement(child)) return;

        const props = child.props as any;
        const hasChildren = props.children != null;
        const isActionLike =
          props.onAction || props.onSubmit || props.content !== undefined || props.url || props.target || props.paths;

        if (isActionLike || (props.title && !hasChildren)) {
          result.push({
            title: inferActionTitle(props),
            icon: props.icon,
            shortcut: props.shortcut,
            style: props.style,
            sectionTitle,
            execute: makeActionExecutor(props, runtimeCtx),
          });
          return;
        }

        if (hasChildren) {
          walk(props.children, props.title || sectionTitle);
        }
      });
    }

    const rootProps = element.props as any;
    if (rootProps?.children) {
      walk(rootProps.children);
    }

    return result;
  }

  function ActionPanelOverlay({
    actions,
    onClose,
    onExecute,
  }: {
    actions: ExtractedAction[];
    onClose: () => void;
    onExecute: (action: ExtractedAction) => void;
  }) {
    const [selectedIdx, setSelectedIdx] = useState(0);
    const [filter, setFilter] = useState('');
    const filterRef = useRef<HTMLInputElement>(null);
    const panelRef = useRef<HTMLDivElement>(null);
    const runtimeCtx = snapshotExtensionContext();
    const assetsPath = String(runtimeCtx?.assetsPath || '').trim();

    const filteredActions = filter
      ? actions.filter((action) => action.title.toLowerCase().includes(filter.toLowerCase()))
      : actions;

    const hasImageExtension = (value: string): boolean => /\.(svg|png|jpe?g|gif|webp|ico|tiff?)$/i.test(value);

    const hasRenderableActionIcon = (icon: ExtractedAction['icon']): boolean => {
      if (!icon) return false;
      if (typeof icon === 'string') {
        return hasImageExtension(icon) ? Boolean(resolveIconSrc(icon, assetsPath)) : true;
      }
      if (typeof icon !== 'object') return true;

      const source = (icon as Record<string, unknown>).source;
      const fallback = (icon as Record<string, unknown>).fallback;
      const fileIcon = (icon as Record<string, unknown>).fileIcon;
      if (typeof fileIcon === 'string' && fileIcon.trim()) return true;

      if (typeof source === 'string') {
        return hasImageExtension(source) ? Boolean(resolveIconSrc(source, assetsPath)) : true;
      }

      if (source && typeof source === 'object') {
        const variants = [source.light, source.dark].filter((value): value is string => typeof value === 'string' && value.trim().length > 0);
        if (variants.length > 0) {
          const assetLikeVariants = variants.filter((value) => hasImageExtension(value));
          if (assetLikeVariants.length === 0) return true;
          if (assetLikeVariants.some((value) => Boolean(resolveIconSrc(value, assetsPath)))) return true;
        }
      }

      if (typeof fallback === 'string' && fallback.trim()) return true;
      return false;
    };

    const hasAnyIcons = filteredActions.some((action) => hasRenderableActionIcon(action.icon));

    useEffect(() => {
      filterRef.current?.focus();
    }, []);

    useEffect(() => {
      setSelectedIdx(0);
    }, [filter]);

    useEffect(() => {
      panelRef.current
        ?.querySelector(`[data-action-idx="${selectedIdx}"]`)
        ?.scrollIntoView({ block: 'nearest' });
    }, [selectedIdx]);

    const handleKeyDown = (event: React.KeyboardEvent) => {
      if ((event.metaKey || event.altKey || event.ctrlKey) && !event.repeat) {
        if (isMetaK(event)) {
          event.preventDefault();
          event.stopPropagation();
          onClose();
          return;
        }

        for (const action of actions) {
          if (!action.shortcut || !matchesShortcut(event, action.shortcut)) continue;
          event.preventDefault();
          event.stopPropagation();
          onExecute(action);
          return;
        }
      }

      switch (event.key) {
        case 'ArrowDown':
          event.preventDefault();
          event.stopPropagation();
          setSelectedIdx((value) => Math.min(value + 1, filteredActions.length - 1));
          break;
        case 'ArrowUp':
          event.preventDefault();
          event.stopPropagation();
          setSelectedIdx((value) => Math.max(value - 1, 0));
          break;
        case 'Enter':
          event.preventDefault();
          event.stopPropagation();
          if (!event.repeat && filteredActions[selectedIdx]) onExecute(filteredActions[selectedIdx]);
          break;
        case 'Escape':
          event.preventDefault();
          event.stopPropagation();
          onClose();
          break;
      }
    };

    const groups: { title?: string; items: { action: ExtractedAction; idx: number }[] }[] = [];
    let groupIndex = 0;
    let currentTitle: string | undefined | null = null;

    for (const action of filteredActions) {
      if (action.sectionTitle !== currentTitle || groups.length === 0) {
        currentTitle = action.sectionTitle;
        groups.push({ title: action.sectionTitle, items: [] });
      }
      groups[groups.length - 1].items.push({ action, idx: groupIndex++ });
    }

    const isGlassyTheme =
      document.documentElement.classList.contains('sc-glassy') ||
      document.body.classList.contains('sc-glassy');
    const isNativeLiquidGlass =
      document.documentElement.classList.contains('sc-native-liquid-glass') ||
      document.body.classList.contains('sc-native-liquid-glass');

    return (
      <div
        className="fixed inset-0 z-50"
        onClick={onClose}
        onKeyDown={handleKeyDown}
        tabIndex={-1}
        style={{ background: 'var(--bg-scrim)' }}
      >
        <div
          ref={panelRef}
          className={`absolute bottom-12 right-3 w-80 max-h-[65vh] overflow-hidden flex flex-col ${
            (isNativeLiquidGlass || isGlassyTheme) ? 'rounded-3xl p-1' : 'rounded-xl shadow-2xl'
          }`}
          style={
            isNativeLiquidGlass
              ? {
                  background: 'rgba(var(--surface-base-rgb), 0.72)',
                  backdropFilter: 'blur(44px) saturate(155%)',
                  WebkitBackdropFilter: 'blur(44px) saturate(155%)',
                  border: '1px solid rgba(var(--on-surface-rgb), 0.22)',
                  boxShadow: `
                    0 18px 38px -12px rgba(var(--backdrop-rgb), 0.26),
                    inset 0 -1px 0 0 rgba(var(--on-surface-rgb), 0.05)
                  `,
                }
              : isGlassyTheme
              ? {
                  background: `
                    linear-gradient(160deg,
                      rgba(255, 255, 255, 0.16) 0%,
                      rgba(255, 255, 255, 0.035) 38%,
                      rgba(255, 255, 255, 0.07) 100%
                    ),
                    rgba(var(--surface-base-rgb), 0.58)
                  `,
                  backdropFilter: 'blur(128px) saturate(195%) contrast(107%) brightness(1.03)',
                  WebkitBackdropFilter: 'blur(128px) saturate(195%) contrast(107%) brightness(1.03)',
                  border: '1px solid rgba(255, 255, 255, 0.14)',
                  boxShadow: `
                    0 28px 58px -14px rgba(0, 0, 0, 0.42),
                    inset 0 -1px 0 0 rgba(0, 0, 0, 0.08)
                  `,
                }
              : {
                  background: 'var(--card-bg)',
                  backdropFilter: 'blur(40px)',
                  WebkitBackdropFilter: 'blur(40px)',
                  border: '1px solid var(--border-primary)',
                }
          }
          onClick={(event) => event.stopPropagation()}
        >
          <div className="action-overlay-scroll flex-1 overflow-y-auto py-1">
            {filteredActions.length === 0 ? (
              <div className="px-3 py-4 text-center text-white/30 text-sm">No matching actions</div>
            ) : (
              groups.map((group, groupPosition) => (
                <div key={groupPosition}>
                  {groupPosition > 0 && <hr className="border-[var(--ui-divider)] my-0.5" />}
                  {group.title && (
                    <div className="px-3 pt-1.5 pb-0.5 text-[10px] uppercase tracking-wider text-white/25 font-medium select-none">
                      {group.title}
                    </div>
                  )}
                  {group.items.map(({ action, idx }) => {
                    const hasActionIcon = hasRenderableActionIcon(action.icon);
                    return (
                    <div
                      key={idx}
                      data-action-idx={idx}
                      className={`mx-1 px-2.5 py-1.5 rounded-lg border border-transparent flex items-center gap-2.5 cursor-pointer transition-colors ${
                        idx === selectedIdx
                          ? 'bg-[var(--action-menu-selected-bg)]'
                          : 'hover:bg-[var(--overlay-item-hover-bg)]'
                      }`}
                      style={
                        idx === selectedIdx
                          ? {
                              background: 'var(--action-menu-selected-bg)',
                              borderColor: 'var(--action-menu-selected-border)',
                              boxShadow: 'var(--action-menu-selected-shadow)',
                            }
                          : undefined
                      }
                      onClick={() => onExecute(action)}
                      onMouseMove={() => setSelectedIdx(idx)}
                    >
                      {hasAnyIcons ? (
                        <span
                          className={`w-4 h-4 flex-shrink-0 flex items-center justify-center text-xs ${
                            idx === selectedIdx ? 'text-white' : 'text-white/50'
                          }`}
                          style={
                            isNativeLiquidGlass && action.style === 'destructive'
                              ? { color: 'var(--status-danger-faded)' }
                              : undefined
                          }
                        >
                          {hasActionIcon ? renderIcon(action.icon, 'w-4 h-4', assetsPath) : null}
                        </span>
                      ) : null}
                      <span
                        className={`flex-1 text-[13px] truncate ${
                          action.style === 'destructive'
                            ? idx === selectedIdx
                              ? 'text-white'
                              : 'text-red-400'
                            : idx === selectedIdx
                              ? 'text-white'
                              : 'text-white/80'
                        }`}
                        style={
                          isNativeLiquidGlass && action.style === 'destructive'
                            ? { color: 'var(--status-danger-faded)' }
                            : undefined
                        }
                      >
                        {action.title}
                      </span>
                      <span className={`flex items-center gap-0.5 ${idx === selectedIdx ? 'text-white/70' : 'text-white/25'}`}>
                        {idx === 0 ? (
                          renderShortcutKeycap('↩', 'enter')
                        ) : (
                          renderShortcut(action.shortcut)
                        )}
                      </span>
                    </div>
                    );
                  })}
                </div>
              ))
            )}
          </div>
          <div className="border-t border-[var(--ui-divider)] px-3 py-2">
            <input
              ref={filterRef}
              type="text"
              placeholder="Search for actions…"
              value={filter}
              onChange={(event) => setFilter(event.target.value)}
              className="w-full bg-transparent text-sm text-white/70 placeholder-white/25 outline-none"
            />
          </div>
        </div>
      </div>
    );
  }

  return {
    extractActionsFromElement,
    ActionPanelOverlay,
  };
}

/**
 * Action runtime React component layer.
 *
 * Exposes `Action` and `ActionPanel` component trees that register actions
 * through the action registry runtime.
 */

import React, { useContext } from 'react';

interface ComponentDeps {
  ActionRegistryContext: React.Context<any>;
  ActionSectionContext: React.Context<string | undefined>;
  useActionRegistration: (props: any, kind?: string) => null;
}

export function createActionComponentRuntime(deps: ComponentDeps) {
  const { ActionRegistryContext, ActionSectionContext, useActionRegistration } = deps;

  function ActionPanelComponent({ children }: { children?: React.ReactNode; title?: string }) {
    const registry = useContext(ActionRegistryContext);
    if (registry) return <>{children}</>;
    return null;
  }

  function ActionPanelSection({ children, title }: { children?: React.ReactNode; title?: string }) {
    const registry = useContext(ActionRegistryContext);
    if (!registry) return null;
    return <ActionSectionContext.Provider value={title}>{children}</ActionSectionContext.Provider>;
  }

  function ActionPanelItem(props: any) {
    useActionRegistration(props, 'action');
    return null;
  }

  function ActionPanelSubmenu({ children, title }: { children?: React.ReactNode; title?: string }) {
    const registry = useContext(ActionRegistryContext);
    if (!registry) return null;
    return <ActionSectionContext.Provider value={title}>{children}</ActionSectionContext.Provider>;
  }

  function ActionComponent(props: any) {
    useActionRegistration(props, 'action');
    return null;
  }

  function createActionKindComponent(kind: string) {
    return function ActionKindComponent(props: any) {
      useActionRegistration({ ...props, __actionKind: kind }, kind);
      return null;
    };
  }

  const ActionPickDateWithType = Object.assign(createActionKindComponent('pickDate'), {
    Type: { DateTime: 'datetime' as const, Date: 'date' as const },
  });

  const Action = Object.assign(ActionComponent, {
    CopyToClipboard: createActionKindComponent('copyToClipboard'),
    Open: createActionKindComponent('open'),
    OpenInBrowser: createActionKindComponent('openInBrowser'),
    Push: createActionKindComponent('push'),
    SubmitForm: createActionKindComponent('submitForm'),
    Paste: createActionKindComponent('paste'),
    ShowInFinder: ActionComponent,
    OpenWith: createActionKindComponent('openWith'),
    Trash: createActionKindComponent('trash'),
    PickDate: ActionPickDateWithType,
    ToggleQuickLook: createActionKindComponent('toggleQuickLook'),
    CreateSnippet: createActionKindComponent('createSnippet'),
    CreateQuicklink: createActionKindComponent('createQuicklink'),
    ToggleSidebar: createActionKindComponent('toggleSidebar'),
    Style: {
      Regular: 'regular' as const,
      Destructive: 'destructive' as const,
    },
  });

  const ActionPanel = Object.assign(ActionPanelComponent, {
    Item: ActionPanelItem,
    Section: ActionPanelSection,
    Submenu: ActionPanelSubmenu,
  });

  return {
    Action,
    ActionPanel,
  };
}

/**
 * Action runtime registry and execution layer.
 *
 * Owns action registration contexts, action execution semantics, and
 * collection of currently mounted actions from extension JSX trees.
 */

import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import type {
  ActionRegistration,
  ActionRegistryAPI,
} from './action-runtime-types';
import { normalizeShortcut } from './action-runtime-shortcuts';

interface RegistryDeps {
  snapshotExtensionContext: () => any;
  withExtensionContext: <T>(ctx: any, callback: () => T) => T;
  ExtensionInfoReactContext: React.Context<{
    extId: string;
    assetsPath: string;
    commandMode: 'view' | 'no-view' | 'menu-bar';
    extensionDisplayName?: string;
    extensionIconDataUrl?: string;
  }>;
  getFormValues: () => Record<string, any>;
  Clipboard: {
    copy: (content: any) => Promise<void> | void;
    paste?: (content: any) => Promise<void> | void;
  };
  trash: (path: string | string[]) => Promise<void> | void;
  getGlobalNavigation: () => { push: (element: React.ReactElement) => void };
}

function parseExtensionIdentity(extId: string): { extensionName: string; commandName: string } | null {
  const raw = String(extId || '').trim();
  const separatorIndex = raw.indexOf('/');
  if (separatorIndex <= 0 || separatorIndex >= raw.length - 1) return null;

  const extensionName = raw.slice(0, separatorIndex).trim();
  const commandName = raw.slice(separatorIndex + 1).trim();
  if (!extensionName || !commandName) return null;

  return { extensionName, commandName };
}

function toLocalDateInputValue(date: Date): string {
  const year = date.getFullYear();
  const month = `${date.getMonth() + 1}`.padStart(2, '0');
  const day = `${date.getDate()}`.padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function toLocalDateTimeInputValue(date: Date): string {
  const datePart = toLocalDateInputValue(date);
  const hours = `${date.getHours()}`.padStart(2, '0');
  const minutes = `${date.getMinutes()}`.padStart(2, '0');
  return `${datePart}T${hours}:${minutes}`;
}

function parseInputDateValue(value: string, type: 'date' | 'datetime'): Date | null {
  const raw = String(value || '').trim();
  if (!raw) return null;

  if (type === 'date') {
    const [yearRaw, monthRaw, dayRaw] = raw.split('-');
    const year = Number(yearRaw);
    const month = Number(monthRaw);
    const day = Number(dayRaw);
    if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) return null;

    const parsed = new Date(year, month - 1, day);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }

  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function normalizePickerDate(value: unknown): Date | null {
  if (!value) return null;
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
  const parsed = new Date(String(value));
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function runPickDateAction(props: any): void {
  const pickerType = props?.type === 'datetime' ? 'datetime' : 'date';
  const inputType = pickerType === 'datetime' ? 'datetime-local' : 'date';

  if (typeof document === 'undefined') {
    props?.onChange?.(null);
    return;
  }

  const input = document.createElement('input');
  input.type = inputType;
  input.style.position = 'fixed';
  input.style.opacity = '0';
  input.style.pointerEvents = 'none';
  input.style.left = '-9999px';
  input.style.top = '-9999px';
  input.tabIndex = -1;
  input.setAttribute('aria-hidden', 'true');

  const initialValue = normalizePickerDate(props?.value);
  if (initialValue) {
    input.value = pickerType === 'datetime'
      ? toLocalDateTimeInputValue(initialValue)
      : toLocalDateInputValue(initialValue);
  }

  const minValue = normalizePickerDate(props?.min);
  if (minValue) {
    input.min = pickerType === 'datetime'
      ? toLocalDateTimeInputValue(minValue)
      : toLocalDateInputValue(minValue);
  }

  const maxValue = normalizePickerDate(props?.max);
  if (maxValue) {
    input.max = pickerType === 'datetime'
      ? toLocalDateTimeInputValue(maxValue)
      : toLocalDateInputValue(maxValue);
  }

  let finished = false;

  const cleanup = () => {
    if (input.parentElement) {
      input.parentElement.removeChild(input);
    }
  };

  const complete = (nextValue: Date | null, shouldEmit: boolean) => {
    if (finished) return;
    finished = true;
    cleanup();
    if (shouldEmit) {
      props?.onChange?.(nextValue);
    }
  };

  input.addEventListener('change', () => {
    complete(parseInputDateValue(input.value, pickerType), true);
  }, { once: true });

  input.addEventListener('blur', () => {
    // On cancel, browsers often blur without firing change.
    window.setTimeout(() => complete(null, false), 0);
  }, { once: true });

  document.body.appendChild(input);
  input.focus({ preventScroll: true });

  const picker = (input as HTMLInputElement & { showPicker?: () => void }).showPicker;
  if (typeof picker === 'function') {
    try {
      picker.call(input);
      return;
    } catch {
      // Fallback to click when showPicker throws due activation constraints.
    }
  }

  input.click();
}

export function createActionRegistryRuntime(deps: RegistryDeps) {
  const {
    snapshotExtensionContext,
    withExtensionContext,
    ExtensionInfoReactContext,
    getFormValues,
    Clipboard,
    trash,
    getGlobalNavigation,
  } = deps;

  let actionOrderCounter = 0;

  const ActionRegistryContext = createContext<ActionRegistryAPI | null>(null);
  const ActionSectionContext = createContext<string | undefined>(undefined);

  function makeActionExecutor(props: any, runtimeCtx?: any): () => void {
    return () => {
      withExtensionContext(runtimeCtx, () => {
        if (props.__actionKind === 'createSnippet') {
          void (window as any).electron?.executeCommand?.('system-create-snippet');
          return;
        }
        if (props.__actionKind === 'createQuicklink') {
          void (window as any).electron?.executeCommand?.('system-create-quicklink');
          return;
        }
        if (props.__actionKind === 'pickDate') {
          runPickDateAction(props);
          return;
        }
        if (props.onAction) {
          return props.onAction();
        }
        if (props.onSubmit) {
          return props.onSubmit(getFormValues());
        }
        if (props.content !== undefined) {
          let op: Promise<void> | void;
          if (props.__actionKind === 'paste') {
            op = Clipboard.paste?.(props.content);
          } else {
            op = Clipboard.copy(props.content);
          }
          props.onCopy?.();
          props.onPaste?.();
          return op;
        }
        if (props.url) {
          (window as any).electron?.openUrl?.(props.url);
          props.onOpen?.();
          return;
        }
        if (props.__actionKind === 'openWith' && props.path) {
          const appName =
            typeof props.application === 'string'
              ? props.application
              : typeof props.application?.name === 'string'
                ? props.application.name
                : undefined;
          (window as any).electron?.openUrl?.(props.path, appName);
          return;
        }
        if (props.target && React.isValidElement(props.target)) {
          getGlobalNavigation().push(props.target);
          props.onPush?.();
          return;
        }
        if (props.paths) {
          const op = trash(props.paths);
          props.onTrash?.();
          return op;
        }
      });
    };
  }

  function inferActionTitle(props: any, kind?: string): string {
    if (props?.title) return props.title;

    switch (kind || props?.__actionKind) {
      case 'copyToClipboard':
        return 'Copy to Clipboard';
      case 'paste':
        return 'Paste';
      case 'openInBrowser':
        return 'Open in Browser';
      case 'push':
        return 'Open';
      case 'submitForm':
        return 'Submit';
      case 'trash':
        return 'Move to Trash';
      case 'pickDate':
        return 'Pick Date';
      case 'open':
        return 'Open';
      case 'openWith': {
        const appName =
          typeof props?.application === 'string'
            ? props.application
            : typeof props?.application?.name === 'string'
              ? props.application.name
              : '';
        return appName ? `Open with ${appName}` : 'Open With...';
      }
      case 'toggleQuickLook':
        return 'Toggle Quick Look';
      case 'createSnippet':
        return 'Create Snippet';
      case 'createQuicklink':
        return 'Create Quicklink';
      case 'toggleSidebar':
        return 'Toggle Sidebar';
      default:
        return 'Action';
    }
  }

  function useActionRegistration(props: any, kind?: string) {
    const registry = useContext(ActionRegistryContext);
    const sectionTitle = useContext(ActionSectionContext);
    const extensionInfo = useContext(ExtensionInfoReactContext);
    const idRef = useRef(`__action_${++actionOrderCounter}`);
    const orderRef = useRef(++actionOrderCounter);
    const runtimeCtxRef = useRef(snapshotExtensionContext());

    const propsRef = useRef(props);
    propsRef.current = props;
    const nextRuntimeCtx = snapshotExtensionContext();
    const extId = String(extensionInfo?.extId || '').trim();
    const parsedIdentity = parseExtensionIdentity(extId);
    if (parsedIdentity?.extensionName) nextRuntimeCtx.extensionName = parsedIdentity.extensionName;
    if (parsedIdentity?.commandName) nextRuntimeCtx.commandName = parsedIdentity.commandName;
    if (extensionInfo?.assetsPath) nextRuntimeCtx.assetsPath = extensionInfo.assetsPath;
    if (extensionInfo?.commandMode) nextRuntimeCtx.commandMode = extensionInfo.commandMode;
    if (extensionInfo?.extensionDisplayName) nextRuntimeCtx.extensionDisplayName = extensionInfo.extensionDisplayName;
    if (extensionInfo?.extensionIconDataUrl) nextRuntimeCtx.extensionIconDataUrl = extensionInfo.extensionIconDataUrl;
    runtimeCtxRef.current = nextRuntimeCtx;

    useEffect(() => {
      if (!registry) return;

      const executor = () => makeActionExecutor(propsRef.current, runtimeCtxRef.current)();
      registry.register(idRef.current, {
        title: inferActionTitle(props, kind),
        icon: props.icon,
        shortcut: normalizeShortcut(props.shortcut),
        style: props.style,
        sectionTitle,
        execute: executor,
        order: orderRef.current,
      });

      return () => registry.unregister(idRef.current);
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [registry, props.title, props.icon, props.shortcut, props.style, sectionTitle]);

    return null;
  }

  function useCollectedActions() {
    const registryRef = useRef(new Map<string, ActionRegistration>());
    const [version, setVersion] = useState(0);
    const pendingRef = useRef(false);
    const lastSnapshotRef = useRef('');

    const scheduleUpdate = useCallback(() => {
      if (pendingRef.current) return;

      pendingRef.current = true;
      queueMicrotask(() => {
        pendingRef.current = false;
        const entries = Array.from(registryRef.current.values());
        const snapshot = entries.map((entry) => `${entry.id}:${entry.title}:${entry.sectionTitle || ''}`).join('|');
        if (snapshot !== lastSnapshotRef.current) {
          lastSnapshotRef.current = snapshot;
          setVersion((value) => value + 1);
        }
      });
    }, []);

    const registryAPI = useMemo<ActionRegistryAPI>(
      () => ({
        register(id, data) {
          const existing = registryRef.current.get(id);
          if (existing) {
            existing.title = data.title;
            existing.icon = data.icon;
            existing.shortcut = data.shortcut;
            existing.style = data.style;
            existing.sectionTitle = data.sectionTitle;
            existing.execute = data.execute;
            existing.order = data.order;
          } else {
            registryRef.current.set(id, { id, ...data });
          }
          scheduleUpdate();
        },
        unregister(id) {
          if (!registryRef.current.has(id)) return;
          registryRef.current.delete(id);
          scheduleUpdate();
        },
      }),
      [scheduleUpdate],
    );

    const collectedActions = useMemo(() => {
      return Array.from(registryRef.current.values()).sort((a, b) => a.order - b.order);
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [version]);

    return { collectedActions, registryAPI };
  }

  return {
    ActionRegistryContext,
    ActionSectionContext,
    makeActionExecutor,
    inferActionTitle,
    useActionRegistration,
    useCollectedActions,
  };
}

/**
 * Action runtime entrypoint.
 *
 * Wires action registry, components, overlay extraction, and keyboard
 * utilities into one runtime consumed by the Raycast API integration layer.
 */

import { createActionComponentRuntime } from './action-runtime-components';
import { createActionOverlayRuntime } from './action-runtime-overlay';
import { createActionRegistryRuntime } from './action-runtime-registry';
import { isMetaK, matchesShortcut, renderShortcut, renderShortcutKeycap } from './action-runtime-shortcuts';
import type React from 'react';

interface ActionRuntimeDeps {
  snapshotExtensionContext: () => any;
  withExtensionContext: <T>(ctx: any, callback: () => T) => T;
  ExtensionInfoReactContext: React.Context<{
    extId: string;
    assetsPath: string;
    commandMode: 'view' | 'no-view' | 'menu-bar';
    extensionDisplayName?: string;
    extensionIconDataUrl?: string;
  }>;
  getFormValues: () => Record<string, any>;
  Clipboard: {
    copy: (content: any) => Promise<void> | void;
    paste?: (content: any) => Promise<void> | void;
  };
  trash: (path: string | string[]) => Promise<void> | void;
  getGlobalNavigation: () => { push: (element: React.ReactElement) => void };
  renderIcon: (icon: any, className?: string, assetsPath?: string) => React.ReactNode;
}

export function createActionRuntime(deps: ActionRuntimeDeps) {
  const registryRuntime = createActionRegistryRuntime({
    snapshotExtensionContext: deps.snapshotExtensionContext,
    withExtensionContext: deps.withExtensionContext,
    ExtensionInfoReactContext: deps.ExtensionInfoReactContext,
    getFormValues: deps.getFormValues,
    Clipboard: deps.Clipboard,
    trash: deps.trash,
    getGlobalNavigation: deps.getGlobalNavigation,
  });

  const componentRuntime = createActionComponentRuntime({
    ActionRegistryContext: registryRuntime.ActionRegistryContext,
    ActionSectionContext: registryRuntime.ActionSectionContext,
    useActionRegistration: registryRuntime.useActionRegistration,
  });

  const overlayRuntime = createActionOverlayRuntime({
    snapshotExtensionContext: deps.snapshotExtensionContext,
    inferActionTitle: registryRuntime.inferActionTitle,
    makeActionExecutor: registryRuntime.makeActionExecutor,
    renderIcon: deps.renderIcon,
    matchesShortcut,
    isMetaK,
    renderShortcut,
    renderShortcutKeycap,
  });

  return {
    ...registryRuntime,
    ...componentRuntime,
    ...overlayRuntime,
    matchesShortcut,
    isMetaK,
    renderShortcut,
    renderShortcutKeycap,
  };
}

