/**
 * raycast-api/oauth/oauth-bridge.ts
 * Purpose: OAuth callback bridge, callback parsing/waiting, and redirect/key helpers.
 */

import { getOAuthRuntimeDeps } from './runtime-config';

const OAUTH_TOKEN_KEY_PREFIX = 'sc-oauth-token:';
const OAUTH_CLIENT_ID_OVERRIDE_PREFIX = 'sc-oauth-client-id:';
const OAUTH_CALLBACK_TIMEOUT_MS = 3 * 60 * 1000;

const oauthCallbackWaiters = new Set<(url: string) => void>();
const oauthCallbackQueue: string[] = [];
let oauthCallbackBridgeInitialized = false;

export function oauthTokenKey(providerId: string): string {
  return `${OAUTH_TOKEN_KEY_PREFIX}${providerId || 'default'}`;
}

export function oauthClientIdOverrideKey(providerId: string): string {
  return `${OAUTH_CLIENT_ID_OVERRIDE_PREFIX}${providerId || 'default'}`;
}

export function ensureOAuthCallbackBridge() {
  if (oauthCallbackBridgeInitialized) return;
  oauthCallbackBridgeInitialized = true;

  try {
    (window as any).electron?.onOAuthCallback?.((url: string) => {
      if (!url) return;
      oauthCallbackQueue.push(url);
      for (const waiter of Array.from(oauthCallbackWaiters)) {
        waiter(url);
      }
    });
  } catch {
    // best-effort
  }
}

function toBase64Url(bytes: Uint8Array): string {
  let binary = '';
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

export function buildOAuthRedirectUri(redirectMethod: string, extensionName?: string): string {
  const pkg = extensionName || getOAuthRuntimeDeps().getExtensionContext().extensionName || 'supercmd-extension';
  switch (redirectMethod) {
    case 'web':
    case 'app':
    case 'appURI':
    default:
      return `supercmd://oauth/callback?packageName=${encodeURIComponent(pkg)}`;
  }
}

export async function buildAuthorizationRequest(params: {
  endpoint: string;
  clientId?: string;
  scope?: string;
  redirectMethod: string;
  extensionName?: string;
  extraParameters?: Record<string, unknown>;
}) {
  const state = Math.random().toString(36).slice(2);
  const codeVerifier = `${Math.random().toString(36).slice(2)}${Math.random().toString(36).slice(2)}${Math.random().toString(36).slice(2)}`;
  const verifierBytes = new TextEncoder().encode(codeVerifier);
  const digest = await crypto.subtle.digest('SHA-256', verifierBytes);
  const codeChallenge = toBase64Url(new Uint8Array(digest));

  const url = new URL(params.endpoint || '');
  if (params.clientId) url.searchParams.set('client_id', params.clientId);
  if (params.scope) url.searchParams.set('scope', params.scope);
  url.searchParams.set('response_type', 'code');
  url.searchParams.set('redirect_uri', buildOAuthRedirectUri(params.redirectMethod, params.extensionName));
  url.searchParams.set('code_challenge', codeChallenge);
  url.searchParams.set('code_challenge_method', 'S256');
  url.searchParams.set('state', state);

  if (params.extraParameters && typeof params.extraParameters === 'object') {
    for (const [k, v] of Object.entries(params.extraParameters)) {
      if (typeof v === 'string') {
        url.searchParams.set(k, v);
      }
    }
  }

  return {
    codeChallenge,
    codeVerifier,
    state,
    redirectUri: buildOAuthRedirectUri(params.redirectMethod, params.extensionName),
    toURL: () => url.toString(),
  };
}

export function parseOAuthCallbackUrl(rawUrl: string): {
  code?: string;
  accessToken?: string;
  tokenType?: string;
  provider?: string;
  state?: string;
  error?: string;
  errorDescription?: string;
} | null {
  try {
    const parsed = new URL(rawUrl);
    if (parsed.protocol !== 'supercmd:') return null;

    const isOAuthCallback =
      (parsed.hostname === 'oauth' && parsed.pathname === '/callback') ||
      parsed.pathname === '/oauth/callback' ||
      (parsed.hostname === 'auth' && parsed.pathname === '/callback') ||
      parsed.pathname === '/auth/callback';

    if (!isOAuthCallback) return null;

    return {
      code: parsed.searchParams.get('code') || undefined,
      accessToken: parsed.searchParams.get('access_token') || undefined,
      tokenType: parsed.searchParams.get('token_type') || undefined,
      provider: parsed.searchParams.get('provider') || undefined,
      state: parsed.searchParams.get('state') || undefined,
      error: parsed.searchParams.get('error') || undefined,
      errorDescription: parsed.searchParams.get('error_description') || undefined,
    };
  } catch {
    return null;
  }
}

export async function waitForOAuthCallback(
  state: string,
  timeoutMs = OAUTH_CALLBACK_TIMEOUT_MS
): Promise<{ code?: string; accessToken?: string; tokenType?: string; provider?: string; error?: string; errorDescription?: string }> {
  ensureOAuthCallbackBridge();

  const stateMatches = (parsed: ReturnType<typeof parseOAuthCallbackUrl>) => {
    if (!parsed) return false;
    if (!state) return true;
    return parsed.state === state;
  };

  for (let i = 0; i < oauthCallbackQueue.length; i++) {
    const parsed = parseOAuthCallbackUrl(oauthCallbackQueue[i]);
    if (stateMatches(parsed)) {
      oauthCallbackQueue.splice(i, 1);
      return parsed!;
    }
  }

  return await new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      oauthCallbackWaiters.delete(handler);
      reject(new Error('OAuth authorization timed out'));
    }, timeoutMs);

    const handler = (rawUrl: string) => {
      const parsed = parseOAuthCallbackUrl(rawUrl);
      if (!stateMatches(parsed)) return;
      clearTimeout(timer);
      oauthCallbackWaiters.delete(handler);
      resolve(parsed!);
    };

    oauthCallbackWaiters.add(handler);
  });
}

/**
 * raycast-api/oauth/with-access-token.tsx
 * Purpose: withAccessToken HOC and access token state helpers.
 */

import React, { useCallback, useEffect, useState } from 'react';
import { Sparkle } from '@phosphor-icons/react';
import { oauthTokenKey, parseOAuthCallbackUrl } from './oauth-bridge';
import { OAuthService } from './oauth-service';
import { getOAuthRuntimeDeps } from './runtime-config';

let accessTokenValue: string | null = null;
let accessTokenType: 'oauth' | 'personal' | null = null;

export function withAccessToken(options: any) {
  const shouldInvokeOnAuthorize = !(options instanceof OAuthService);
  const authorizeForNoView = async (): Promise<void> => {
    if (options instanceof OAuthService) {
      if (options?.personalAccessToken) {
        accessTokenValue = options.personalAccessToken;
        accessTokenType = 'personal';
        await Promise.resolve(options.onAuthorize?.({ token: accessTokenValue, type: 'personal' }));
        return;
      }

      let stored = await options.getStoredToken();
      if (!stored?.token) {
        const authorized = await options.beginAuthorization();
        if (!authorized) {
          throw new Error('OAuth authorization is required');
        }
        stored = await options.getStoredToken();
      }

      if (!stored?.token) {
        throw new Error('OAuth authorization failed');
      }

      accessTokenValue = stored.token;
      accessTokenType = 'oauth';
      await Promise.resolve(options.onAuthorize?.({ token: stored.token, type: 'oauth', idToken: stored.idToken }));
      return;
    }

    const token = options?.personalAccessToken ?? (await options?.authorize?.());
    if (!token) {
      throw new Error('No access token returned');
    }
    accessTokenValue = token;
    accessTokenType = options?.personalAccessToken ? 'personal' : 'oauth';
    const idToken = (await options?.client?.getTokens?.())?.idToken;
    if (shouldInvokeOnAuthorize) {
      await Promise.resolve(options?.onAuthorize?.({ token, type: accessTokenType, idToken }));
    }
  };

  return (Component: any) => {
    const WrappedComponent: React.FC<any> = (props) => {
      const [ready, setReady] = useState(false);
      const [error, setError] = useState<string | null>(null);
      const [oauthNeedsAuth, setOauthNeedsAuth] = useState(false);
      const [oauthBusy, setOauthBusy] = useState(false);
      const [oauthLink, setOauthLink] = useState<string>('');
      const [oauthInfo, setOauthInfo] = useState<{ name: string; description: string; icon?: string } | null>(null);
      const [oauthHint, setOauthHint] = useState<string>('');
      const [oauthClientIdInput, setOauthClientIdInput] = useState('');

      const refreshOAuthState = useCallback(async () => {
        if (!(options instanceof OAuthService)) return false;
        const stored = await options.getStoredToken();
        if (!stored?.token) return false;

        accessTokenValue = stored.token;
        accessTokenType = 'oauth';
        await Promise.resolve(options.onAuthorize?.({ token: stored.token, type: 'oauth', idToken: stored.idToken }));
        setOauthNeedsAuth(false);
        setReady(true);
        setOauthBusy(false);
        setOauthHint('');
        return true;
      }, [options]);

      // Clear OAuth blur-hide suppression when the component unmounts.
      // beginAuthorization() sets oauthSetFlowActive(true) and awaits the
      // callback — if the user navigates away before the callback arrives,
      // the suppression would otherwise persist until the 3-minute timeout.
      useEffect(() => {
        return () => {
          (window as any).electron?.oauthSetFlowActive?.(false)?.catch?.(() => {});
        };
      }, []);

      useEffect(() => {
        let cancelled = false;

        (async () => {
          try {
            if (options instanceof OAuthService) {
              const info = options.getProviderInfo();
              if (!cancelled) setOauthInfo(info);
              if (!cancelled) setOauthClientIdInput(options.getConfiguredClientId() || '');

              const authUrl = await options.getAuthorizationUrl();
              if (!cancelled) setOauthLink(authUrl || '');

              const ok = await refreshOAuthState();
              if (!ok && !cancelled) {
                setOauthNeedsAuth(true);
              }
              return;
            }

            const token = options?.personalAccessToken ?? (await options?.authorize?.());
            if (!token) throw new Error('No access token returned');

            accessTokenValue = token;
            accessTokenType = options?.personalAccessToken ? 'personal' : 'oauth';

            const idToken = (await options?.client?.getTokens?.())?.idToken;
            if (shouldInvokeOnAuthorize) {
              await Promise.resolve(options?.onAuthorize?.({ token, type: accessTokenType, idToken }));
            }

            if (!cancelled) setReady(true);
          } catch (e: any) {
            if (!cancelled) setError(e?.message || 'Failed to authorize');
          }
        })();

        return () => {
          cancelled = true;
        };
      }, [options, refreshOAuthState, shouldInvokeOnAuthorize]);

      useEffect(() => {
        if (!(options instanceof OAuthService)) return;

        const off = (window as any).electron?.onOAuthCallback?.((rawUrl: string) => {
          (async () => {
            const parsed = parseOAuthCallbackUrl(rawUrl);
            if (!parsed) return;

            if (parsed.error) {
              setOauthBusy(false);
              setOauthHint(parsed.errorDescription || parsed.error);
              return;
            }

            const providerKey = options.getProviderKey();
            if (parsed.provider && parsed.provider !== providerKey) return;

            const callbackToken = parsed.accessToken || parsed.code;
            if (callbackToken) {
              const tokenPayload = {
                accessToken: callbackToken,
                tokenType: parsed.tokenType || 'Bearer',
                scope: '',
                obtainedAt: new Date().toISOString(),
              };

              try {
                localStorage.setItem(oauthTokenKey(providerKey), JSON.stringify(tokenPayload));
              } catch {
                // best-effort
              }
              try {
                await (window as any).electron?.oauthSetToken?.(providerKey, tokenPayload);
              } catch {
                // best-effort
              }
            }

            const refreshed = await refreshOAuthState();
            if (!refreshed) {
              setOauthBusy(false);
              setOauthNeedsAuth(true);
              setOauthHint('Authorization callback received. Please try again.');
            }
          })().catch(() => {
            setOauthBusy(false);
          });
        });

        return () => {
          if (typeof off === 'function') off();
        };
      }, [options, refreshOAuthState]);

      useEffect(() => {
        if (!(options instanceof OAuthService) || !oauthBusy || !oauthNeedsAuth) return;

        let cancelled = false;
        let attempts = 0;
        const maxAttempts = 40;

        const tick = async () => {
          if (cancelled) return;
          attempts += 1;

          const refreshed = await refreshOAuthState();
          if (cancelled || refreshed) return;

          if (attempts >= maxAttempts) {
            setOauthBusy(false);
            setOauthHint('Authorization completed, but finalizing took too long. Try opening once more.');
            return;
          }

          setTimeout(() => {
            void tick();
          }, 500);
        };

        void tick();
        return () => {
          cancelled = true;
        };
      }, [options, oauthBusy, oauthNeedsAuth, refreshOAuthState]);

      const handleOAuthSignIn = useCallback(async () => {
        if (!(options instanceof OAuthService)) return;

        setOauthBusy(true);
        setOauthHint('');
        try {
          options.setClientIdOverride(oauthClientIdInput);
          const opened = await options.beginAuthorization();
          if (!opened) {
            setOauthHint('Unable to open authorization URL.');
            return;
          }

          const refreshed = await refreshOAuthState();
          if (!refreshed) {
            setOauthHint('Authorization finished but no token was stored.');
          }
        } catch (e: any) {
          setOauthHint(e?.message || 'Failed to start OAuth authorization.');
        } finally {
          setOauthBusy(false);
        }
      }, [oauthClientIdInput, options, refreshOAuthState]);

      const handleOAuthCopyLink = useCallback(async () => {
        if (!oauthLink) return;

        try {
          await navigator.clipboard.writeText(oauthLink);
          setOauthHint('Authorization link copied.');
        } catch {
          setOauthHint('Failed to copy authorization link.');
        }
      }, [oauthLink]);

      if (error) {
        return <div style={{ padding: 16, color: 'rgba(var(--on-surface-rgb), 0.8)', fontSize: 13 }}>{error}</div>;
      }

      if (oauthNeedsAuth) {
        const deps = getOAuthRuntimeDeps();
        const providerIconSrc = oauthInfo?.icon ? deps.resolveIconSrc(String(oauthInfo.icon)) : '';
        const extensionIconSrc = deps.getExtensionContext().extensionIconDataUrl || '';
        const iconSrc = providerIconSrc || extensionIconSrc;

        return (
          <div className="h-full flex flex-col">
            <div className="flex-1 flex items-center justify-center px-6">
              <div className="w-full max-w-[520px] text-center">
                <div className="mx-auto mb-5 w-14 h-14 rounded-2xl bg-white/[0.04] flex items-center justify-center overflow-hidden">
                  {iconSrc ? <img src={iconSrc} alt="" className="w-9 h-9 object-contain" /> : <Sparkle className="w-5 h-5 text-white/70" />}
                </div>
                <div className="text-white/95 text-[34px] leading-tight font-semibold mb-1">{oauthInfo?.name || 'Sign In Required'}</div>
                <div className="text-white/60 text-[15px] mb-6">{oauthInfo?.description || 'Connect your account to continue.'}</div>
                <button
                  type="button"
                  onClick={handleOAuthSignIn}
                  disabled={oauthBusy}
                  className={`inline-flex items-center gap-2 px-4 py-2.5 rounded-lg text-sm font-semibold border border-transparent transition-colors shadow-[inset_0_1px_0_rgba(255,255,255,0.08),0_8px_24px_rgba(0,0,0,0.28)] ${oauthBusy ? 'bg-white/[0.08] text-white/45 cursor-not-allowed' : 'bg-white/[0.14] hover:bg-white/[0.18] text-white'}`}
                >
                  {oauthBusy ? 'Opening...' : `Sign in with ${oauthInfo?.name || 'Provider'}`}
                </button>
              </div>
            </div>
            <div className="px-4 py-3 text-center text-sm text-white/55">
              Need to open in another browser?{' '}
              <button type="button" onClick={handleOAuthCopyLink} className="text-cyan-300 hover:text-cyan-200 transition-colors">
                Copy authorization link
              </button>
              {oauthHint ? <div className="mt-1 text-xs text-white/40">{oauthHint}</div> : null}
            </div>
          </div>
        );
      }

      if (!ready) {
        return <div style={{ padding: 16, color: 'rgba(var(--on-surface-rgb), 0.55)', fontSize: 13 }}>Authorizing...</div>;
      }

      return <Component {...props} />;
    };

    const WrappedNoViewOrComponent = (props: any) => {
      const mode = getOAuthRuntimeDeps().getExtensionContext().commandMode;
      if (mode === 'no-view') {
        return (async () => {
          await authorizeForNoView();
          return await Component(props);
        })();
      }
      return <WrappedComponent {...props} />;
    };

    WrappedNoViewOrComponent.displayName = `withAccessToken(${Component?.displayName || Component?.name || 'Component'})`;
    return WrappedNoViewOrComponent;
  };
}

export function getAccessToken(): { token: string; type: 'oauth' | 'personal' } {
  if (!accessTokenValue || !accessTokenType) {
    throw new Error('getAccessToken must be used when authenticated');
  }
  return { token: accessTokenValue, type: accessTokenType };
}

export function resetAccessToken(): void {
  accessTokenValue = null;
  accessTokenType = null;
}

/**
