/**
 * raycast-api/oauth/oauth-service-core.ts
 * Purpose: OAuthService core flow (authorize URL creation, callback wait, token exchange).
 */
import { buildOAuthRedirectUri, ensureOAuthCallbackBridge, oauthClientIdOverrideKey, waitForOAuthCallback } from './oauth-bridge';
import { buildDefaultRedirectUri } from './oauth-client';
import type { OAuthProviderInfo, OAuthServiceOptions } from './oauth-types';
import { getOAuthRuntimeDeps } from './runtime-config';
export class OAuthServiceCore {
  protected options: OAuthServiceOptions;
  onAuthorize?: OAuthServiceOptions['onAuthorize'];

  constructor(options: OAuthServiceOptions) {
    this.options = options || {};
    this.onAuthorize = options?.onAuthorize;
  }

  getProviderKey(): string {
    return this.options.client?.providerId || this.options.client?.providerName || 'oauth-provider';
  }

  getConfiguredClientId(): string | undefined {
    const key = oauthClientIdOverrideKey(this.getProviderKey());
    const override = localStorage.getItem(key);
    return (override && override.trim()) || this.options.clientId;
  }

  setClientIdOverride(value: string): void {
    const key = oauthClientIdOverrideKey(this.getProviderKey());
    const trimmed = (value || '').trim();
    if (!trimmed) {
      localStorage.removeItem(key);
      return;
    }
    localStorage.setItem(key, trimmed);
  }

  protected getManagedAuthorizeUrl(): string | null {
    const providerId = String(this.options.client?.providerId || '').trim().toLowerCase();
    const providerName = String(this.options.client?.providerName || '').trim().toLowerCase();
    const configuredAuthorizeUrl = String(this.options.authorizeUrl || '').trim().toLowerCase();

    if (
      providerId === 'spotify' ||
      providerName === 'spotify' ||
      configuredAuthorizeUrl.includes('accounts.spotify.com/authorize')
    ) {
      return 'https://api.supercmd.sh/auth/spotify/authorize';
    }

    if (
      providerId === 'linear' ||
      providerName === 'linear' ||
      configuredAuthorizeUrl.includes('api.linear.app/oauth/authorize')
    ) {
      return 'https://api.supercmd.sh/auth/linear/authorize';
    }

    return null;
  }

  protected async exchangeAuthorizationCode(params: {
    code: string;
    codeVerifier: string;
    redirectUri: string;
  }): Promise<any> {
    if (!this.options.tokenUrl) {
      throw new Error('OAuth token URL is not configured for this extension.');
    }

    const clientId = this.getConfiguredClientId();
    if (!clientId) {
      throw new Error('Missing OAuth client ID. Configure a valid client ID and try again.');
    }

    const body = new URLSearchParams();
    body.set('grant_type', 'authorization_code');
    body.set('code', params.code);
    body.set('client_id', clientId);
    body.set('redirect_uri', params.redirectUri);
    body.set('code_verifier', params.codeVerifier);

    const response = await fetch(this.options.tokenUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Accept: 'application/json',
      },
      body: body.toString(),
    });

    const text = await response.text();
    let parsed: any = null;
    try {
      parsed = text ? JSON.parse(text) : null;
    } catch {
      // best-effort
    }

    if (!response.ok) {
      const providerError =
        parsed?.error_description ||
        parsed?.error?.message ||
        parsed?.error ||
        text ||
        `OAuth token exchange failed (${response.status})`;
      throw new Error(providerError);
    }

    return parsed || {};
  }

  getProviderInfo(): OAuthProviderInfo {
    return {
      name: this.options.client?.providerName || 'OAuth Provider',
      description: this.options.client?.description || `Connect your ${this.options.client?.providerName || 'account'}`,
      icon: this.options.client?.providerIcon,
    };
  }

  async getAuthorizationUrl(): Promise<string | null> {
    const managedAuthorizeUrl = this.getManagedAuthorizeUrl();
    if (managedAuthorizeUrl) return managedAuthorizeUrl;

    if (!this.options.authorizeUrl || !this.options.scope) return null;

    const clientId = this.getConfiguredClientId();
    if (!clientId) return null;

    try {
      if (this.options.client?.authorizationRequest) {
        const request = await this.options.client.authorizationRequest({
          endpoint: this.options.authorizeUrl,
          clientId,
          scope: this.options.scope,
        });
        if (request?.toURL) return request.toURL();
      }

      const url = new URL(this.options.authorizeUrl);
      url.searchParams.set('client_id', clientId);
      url.searchParams.set('scope', this.options.scope);
      url.searchParams.set('response_type', 'code');
      url.searchParams.set(
        'redirect_uri',
        buildOAuthRedirectUri((this.options.client as any)?.redirectMethod || 'web', (this.options.client as any)?.extensionName)
      );
      return url.toString();
    } catch {
      return null;
    }
  }

  async beginAuthorization(): Promise<boolean> {
    try {
      await (window as any).electron?.oauthSetFlowActive?.(true);
    } catch {
      // best-effort
    }

    try {
      if (typeof this.options.authorize === 'function') {
        ensureOAuthCallbackBridge();
        const token = await this.options.authorize();
        if (!token) return false;

        const tokenSet = {
          accessToken: token,
          scope: this.options.scope || '',
          tokenType: 'Bearer',
          obtainedAt: new Date().toISOString(),
        };
        await this.options.client?.setTokens?.(tokenSet);
        await Promise.resolve(this.onAuthorize?.({ token, type: 'oauth' }));
        return true;
      }

      const managedAuthorizeUrl = this.getManagedAuthorizeUrl();
      if (managedAuthorizeUrl) {
        ensureOAuthCallbackBridge();
        await getOAuthRuntimeDeps().open(managedAuthorizeUrl);
        const callback = await waitForOAuthCallback('');
        if (callback.error) throw new Error(callback.errorDescription || callback.error);

        const token = callback.accessToken || callback.code;
        if (!token) throw new Error('Authorization did not return a valid token.');

        const tokenSet = {
          accessToken: token,
          scope: this.options.scope || '',
          tokenType: callback.tokenType || 'Bearer',
          obtainedAt: new Date().toISOString(),
        };
        await this.options.client?.setTokens?.(tokenSet);
        await Promise.resolve(this.onAuthorize?.({ token, type: 'oauth' }));
        return true;
      }

      const clientId = this.getConfiguredClientId();
      if (!clientId || !this.options.authorizeUrl || !this.options.scope) return false;

      const request = await this.options.client?.authorizationRequest?.({
        endpoint: this.options.authorizeUrl,
        clientId,
        scope: this.options.scope,
      });

      const authUrl = request?.toURL ? request.toURL() : await this.getAuthorizationUrl();
      if (!authUrl) return false;

      await getOAuthRuntimeDeps().open(authUrl);
      const callback = await waitForOAuthCallback(request?.state || '');

      if (callback.error) throw new Error(callback.errorDescription || callback.error);

      const directToken = callback.accessToken;
      if (directToken) {
        const tokenSet = {
          accessToken: directToken,
          scope: this.options.scope || '',
          tokenType: callback.tokenType || 'Bearer',
          obtainedAt: new Date().toISOString(),
        };
        await this.options.client?.setTokens?.(tokenSet);
        await Promise.resolve(this.onAuthorize?.({ token: directToken, type: 'oauth' }));
        return true;
      }

      if (!callback.code) throw new Error('Authorization did not return a valid code.');

      const tokenResponse = await this.exchangeAuthorizationCode({
        code: callback.code,
        codeVerifier: request?.codeVerifier || '',
        redirectUri: request?.redirectUri || buildDefaultRedirectUri((this.options.client as any)?.redirectMethod || 'web'),
      });

      const accessToken = tokenResponse?.access_token || tokenResponse?.accessToken;
      if (!accessToken) throw new Error('OAuth token response did not include an access token.');

      const tokenSet = {
        accessToken,
        refreshToken: tokenResponse?.refresh_token || tokenResponse?.refreshToken,
        idToken: tokenResponse?.id_token || tokenResponse?.idToken,
        scope: tokenResponse?.scope || this.options.scope || '',
        tokenType: tokenResponse?.token_type || tokenResponse?.tokenType || 'Bearer',
        expiresIn: tokenResponse?.expires_in || tokenResponse?.expiresIn,
        obtainedAt: new Date().toISOString(),
      };

      await this.options.client?.setTokens?.(tokenSet);
      await Promise.resolve(
        this.onAuthorize?.({ token: tokenSet.accessToken, type: 'oauth', idToken: tokenSet.idToken })
      );
      return true;
    } finally {
      try {
        await (window as any).electron?.oauthSetFlowActive?.(false);
      } catch {
        // best-effort
      }
    }
  }

  async getStoredToken(): Promise<{ token: string; idToken?: string } | null> {
    const stored = await this.options.client?.getTokens?.();
    const accessToken = stored?.accessToken || stored?.access_token;
    if (!accessToken) return null;

    const idToken = stored?.idToken || stored?.id_token;
    return { token: accessToken, idToken };
  }

  async authorize(): Promise<string> {
    if (this.options.personalAccessToken) {
      const token = this.options.personalAccessToken;
      await Promise.resolve(this.onAuthorize?.({ token, type: 'personal' }));
      return token;
    }

    if (typeof this.options.authorize === 'function') {
      const token = await this.options.authorize();
      await this.options.client?.setTokens?.({ accessToken: token, tokenType: 'Bearer', scope: this.options.scope || '' });
      await Promise.resolve(this.onAuthorize?.({ token, type: 'oauth' }));
      return token;
    }

    const stored = await this.getStoredToken();
    if (stored?.token) {
      await Promise.resolve(this.onAuthorize?.({ token: stored.token, type: 'oauth', idToken: stored.idToken }));
      return stored.token;
    }

    const ok = await this.beginAuthorization();
    if (!ok) throw new Error('OAuth authorization is required');

    const postAuth = await this.getStoredToken();
    if (!postAuth?.token) throw new Error('OAuth authorization failed');
    return postAuth.token;
  }
}

/**
 * raycast-api/storage-events.ts
 * Purpose: Shared extension storage change event bridge.
 */

type ExtensionCtx = { extensionName?: string };

let getExtensionContextRef: () => ExtensionCtx = () => ({ extensionName: '' });

export function configureStorageEvents(deps: { getExtensionContext: () => ExtensionCtx }) {
  getExtensionContextRef = deps.getExtensionContext;
}

export function emitExtensionStorageChanged(): void {
  try {
    const extensionName = (getExtensionContextRef().extensionName || '').trim();
    if (!extensionName) return;

    window.dispatchEvent(
      new CustomEvent('sc-extension-storage-changed', {
        detail: { extensionName },
      })
    );
  } catch {
    // best-effort
  }
}

/**
 * raycast-api/hooks/use-local-storage.ts
 * Purpose: useLocalStorage hook.
 */

import { useCallback, useState } from 'react';
import { emitExtensionStorageChanged } from '../storage-events';
import { getScopedLocalStorageKeys, readScopedJsonState } from './storage-scope';

export function useLocalStorage<T>(
  key: string,
  initialValue?: T
): {
  value: T | undefined;
  setValue: (value: T) => Promise<void>;
  removeValue: () => Promise<void>;
  isLoading: boolean;
} {
  const { scopedKey, legacyKeys } = getScopedLocalStorageKeys(key);
  const [value, setValueState] = useState<T | undefined>(() => {
    return readScopedJsonState(scopedKey, legacyKeys, initialValue);
  });
  const [isLoading] = useState(false);

  const setValue = useCallback(async (newValue: T) => {
    setValueState(newValue);
    try {
      localStorage.setItem(scopedKey, JSON.stringify(newValue));
    } catch {
      // best-effort
    }
    emitExtensionStorageChanged();
  }, [scopedKey]);

  const removeValue = useCallback(async () => {
    setValueState(undefined);
    try {
      localStorage.removeItem(scopedKey);
      for (const legacyKey of legacyKeys) {
        localStorage.removeItem(legacyKey);
      }
    } catch {
      // best-effort
    }
    emitExtensionStorageChanged();
  }, [legacyKeys, scopedKey]);

  return { value, setValue, removeValue, isLoading };
}

import { getCurrentScopedExtensionContext } from '../context-scope-runtime';

function getExtensionStorageScope(): string {
  return String(getCurrentScopedExtensionContext()?.extensionName || '').trim() || 'global';
}

function readJsonValue(raw: string | null): unknown {
  if (!raw) return undefined;
  try {
    return JSON.parse(raw);
  } catch {
    return undefined;
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function isCompatibleStoredValue(storedValue: unknown, initialValue: unknown): boolean {
  if (initialValue === undefined) return true;
  if (initialValue === null) return storedValue === null;
  if (Array.isArray(initialValue)) return Array.isArray(storedValue);

  const initialType = typeof initialValue;
  if (initialType !== 'object') return typeof storedValue === initialType;
  if (isPlainObject(initialValue)) return isPlainObject(storedValue);

  return typeof storedValue === 'object';
}

export function getScopedCachedStateKeys(key: string, cacheNamespace?: string): { scopedKey: string; legacyKeys: string[] } {
  const namespacePrefix = cacheNamespace ? `${cacheNamespace}-` : '';
  return {
    scopedKey: `sc-cache:${getExtensionStorageScope()}:${namespacePrefix}${key}`,
    legacyKeys: [`sc-cache-${namespacePrefix}${key}`],
  };
}

export function getScopedLocalStorageKeys(key: string): { scopedKey: string; legacyKeys: string[] } {
  return {
    scopedKey: `raycast:${getExtensionStorageScope()}:${key}`,
    legacyKeys: [`raycast-${key}`],
  };
}

export function readScopedJsonState<T>(
  scopedKey: string,
  legacyKeys: string[],
  initialValue?: T,
): T | undefined {
  const scopedValue = readJsonValue(localStorage.getItem(scopedKey));
  if (scopedValue !== undefined && isCompatibleStoredValue(scopedValue, initialValue)) {
    return scopedValue as T;
  }

  for (const legacyKey of legacyKeys) {
    const legacyValue = readJsonValue(localStorage.getItem(legacyKey));
    if (legacyValue === undefined || !isCompatibleStoredValue(legacyValue, initialValue)) continue;
    try {
      localStorage.setItem(scopedKey, JSON.stringify(legacyValue));
    } catch {
      // best-effort migration
    }
    return legacyValue as T;
  }

  return initialValue;
}

/**
 * raycast-api/hooks/use-cached-state.ts
 * Purpose: useCachedState hook.
 */

import { useCallback, useState } from 'react';
import { getScopedCachedStateKeys, readScopedJsonState } from './storage-scope';

export function useCachedState<T>(
  key: string,
  initialValue?: T,
  config?: { cacheNamespace?: string }
): [T, (value: T | ((prev: T) => T)) => void] {
  const { scopedKey, legacyKeys } = getScopedCachedStateKeys(key, config?.cacheNamespace);
  const [value, setValue] = useState<T>(() => {
    return readScopedJsonState(scopedKey, legacyKeys, initialValue) as T;
  });

  const setter = useCallback((newValue: T | ((prev: T) => T)) => {
    setValue((prev) => {
      const resolved = typeof newValue === 'function' ? (newValue as (prev: T) => T)(prev) : newValue;
      try {
        localStorage.setItem(scopedKey, JSON.stringify(resolved));
      } catch {
        // best-effort
      }
      return resolved;
    });
  }, [scopedKey]);

  return [value, setter];
}

/**
 * raycast-api/hooks/use-cached-promise.ts
 * Purpose: useCachedPromise hook.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { snapshotExtensionContext, withExtensionContext, type ExtensionContextSnapshot } from '../context-scope-runtime';

function resolveInitialDataValue<T>(value: T | (() => T) | undefined): T | undefined {
  if (typeof value === 'function') {
    try {
      return (value as () => T)();
    } catch {
      return undefined;
    }
  }
  return value;
}

export function useCachedPromise<T>(
  fn: (...args: any[]) => Promise<T> | ((...args: any[]) => (...innerArgs: any[]) => Promise<any>),
  args?: any[],
  options?: {
    initialData?: T | (() => T);
    execute?: boolean;
    keepPreviousData?: boolean;
    abortable?: React.MutableRefObject<AbortController | null | undefined>;
    onData?: (data: T) => void;
    onError?: (error: Error) => void;
    onWillExecute?: (args: any[]) => void;
    failureToastOptions?: any;
  }
): {
  data: T | undefined;
  isLoading: boolean;
  error: Error | undefined;
  revalidate: () => void;
  mutate: (asyncUpdate?: Promise<T>, options?: any) => Promise<T | undefined>;
  pagination?: { page: number; pageSize: number; hasMore: boolean; onLoadMore: () => void };
} {
  const [page, setPage] = useState(0);
  const [cursor, setCursor] = useState<string | undefined>(undefined);
  const [hasMore, setHasMore] = useState(true);
  const [accumulatedData, setAccumulatedData] = useState<any | undefined>(() => resolveInitialDataValue(options?.initialData));
  const [isLoading, setIsLoading] = useState(options?.execute !== false);
  const [error, setError] = useState<Error | undefined>(undefined);
  const [isPaginated, setIsPaginated] = useState(false);

  const mountedRef = useRef(true);
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  const fnRef = useRef(fn);
  const argsRef = useRef(args || []);
  const optionsRef = useRef(options);
  const runtimeCtxRef = useRef<ExtensionContextSnapshot>(snapshotExtensionContext());
  fnRef.current = fn;
  argsRef.current = args || [];
  optionsRef.current = options;
  runtimeCtxRef.current = snapshotExtensionContext();

  const fetchPage = useCallback(async (pageNum: number, currentCursor?: string) => {
    const opts = optionsRef.current;
    if (opts?.execute === false || !mountedRef.current) return;

    setIsLoading(true);
    setError(undefined);

    if (opts?.abortable) {
      const controller = new AbortController();
      opts.abortable.current = controller;
    }

    withExtensionContext(runtimeCtxRef.current, () => {
      opts?.onWillExecute?.(argsRef.current);
    });

    try {
      const outerResult = withExtensionContext(runtimeCtxRef.current, () => fnRef.current(...argsRef.current));

      if (typeof outerResult === 'function') {
        setIsPaginated(true);
        const paginationOptions = { page: pageNum, cursor: currentCursor, lastItem: undefined };
        const innerResult = await withExtensionContext(runtimeCtxRef.current, () => outerResult(paginationOptions));
        if (!mountedRef.current) return;

        if (innerResult && typeof innerResult === 'object' && 'data' in innerResult) {
          const { data: pageData, hasMore: more, cursor: nextCursor } = innerResult;
          setHasMore(more ?? false);
          setCursor(nextCursor);

          if (pageNum === 0) {
            setAccumulatedData(Array.isArray(pageData) ? pageData : []);
          } else {
            setAccumulatedData((prev) => {
              const prevArr = Array.isArray(prev) ? prev : [];
              const newArr = Array.isArray(pageData) ? pageData : [];
              return [...prevArr, ...newArr];
            });
          }

          withExtensionContext(runtimeCtxRef.current, () => {
            opts?.onData?.((innerResult as any).data);
          });
        } else {
          setAccumulatedData(innerResult as any);
          setHasMore(false);
        }
      } else {
        const result = await outerResult;
        if (!mountedRef.current) return;

        if (result && typeof result === 'object' && 'data' in result && 'hasMore' in result) {
          setIsPaginated(true);
          const { data: pageData, hasMore: more, cursor: nextCursor } = result as any;
          setHasMore(more ?? false);
          setCursor(nextCursor);

          if (pageNum === 0) {
            setAccumulatedData(Array.isArray(pageData) ? pageData : []);
          } else {
            setAccumulatedData((prev) => {
              const prevArr = Array.isArray(prev) ? prev : [];
              const newArr = Array.isArray(pageData) ? pageData : [];
              return [...prevArr, ...newArr];
            });
          }

          withExtensionContext(runtimeCtxRef.current, () => {
            opts?.onData?.(pageData as T);
          });
        } else {
          setAccumulatedData(result as any);
          setHasMore(false);
          withExtensionContext(runtimeCtxRef.current, () => {
            opts?.onData?.(result as T);
          });
        }
      }
    } catch (err) {
      if (!mountedRef.current) return;
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      withExtensionContext(runtimeCtxRef.current, () => {
        opts?.onError?.(e);
      });
    } finally {
      if (mountedRef.current) setIsLoading(false);
    }
  }, []);

  const argsKey = JSON.stringify(args || []);
  useEffect(() => {
    setPage(0);
    setCursor(undefined);
    if (!optionsRef.current?.keepPreviousData) {
      setAccumulatedData(resolveInitialDataValue(optionsRef.current?.initialData));
    }
    fetchPage(0, undefined);
  }, [argsKey, fetchPage]);

  const revalidate = useCallback(() => {
    setPage(0);
    setCursor(undefined);
    if (!optionsRef.current?.keepPreviousData) {
      setAccumulatedData(resolveInitialDataValue(optionsRef.current?.initialData));
    }
    fetchPage(0, undefined);
  }, [fetchPage]);

  const mutate = useCallback(async (asyncUpdate?: Promise<T>, mutateOptions?: any) => {
    const previousData = accumulatedData as T | undefined;

    if (mutateOptions?.optimisticUpdate) {
      try {
        setAccumulatedData(mutateOptions.optimisticUpdate(previousData));
      } catch {
        setAccumulatedData(previousData as any);
      }
    }

    if (asyncUpdate) {
      try {
        const result = await asyncUpdate;
        if (!mutateOptions?.shouldRevalidateAfter) {
          setAccumulatedData(result as any);
        }
        if (mutateOptions?.shouldRevalidateAfter) {
          revalidate();
        }
        return result;
      } catch (error) {
        if (mutateOptions?.rollbackOnError) {
          try {
            setAccumulatedData(mutateOptions.rollbackOnError(previousData));
          } catch {
            setAccumulatedData(previousData as any);
          }
        }
        throw error;
      }
    }

    revalidate();
    return previousData;
  }, [accumulatedData, revalidate]);

  const onLoadMore = useCallback(() => {
    if (hasMore && !isLoading) {
      const nextPage = page + 1;
      setPage(nextPage);
      fetchPage(nextPage, cursor);
    }
  }, [hasMore, isLoading, page, cursor, fetchPage]);

  const pagination = useMemo(() => ({
    page,
    pageSize: 10,
    hasMore,
    onLoadMore,
  }), [page, hasMore, onLoadMore]);

  return {
    data: accumulatedData as T | undefined,
    isLoading,
    error,
    revalidate,
    mutate,
    pagination: isPaginated ? pagination : undefined,
  };
}

